CREATE OR REPLACE FUNCTION private.gridex_calculate_spot_price_month_v1(p_source text, p_price_area text, p_billing_month text)
 RETURNS TABLE(period_start timestamp with time zone, period_end timestamp with time zone, average_sek_per_kwh numeric, min_sek_per_kwh numeric, max_sek_per_kwh numeric, interval_count integer, expected_interval_count integer, covered_duration_minutes bigint, expected_duration_minutes bigint, quality_issues jsonb, provider_fetched_at timestamp with time zone, verified_at timestamp with time zone, status text, source_checksum text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_month_start_date date;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_expected_days integer;
  v_verified_days integer;
  v_expected_intervals integer;
  v_actual_intervals integer;
  v_expected_minutes bigint;
  v_covered_minutes bigint;
  v_avg numeric;
  v_min numeric;
  v_max numeric;
  v_checksum text;
  v_complete boolean;
  v_now timestamptz := now();
begin
  if p_source is null or nullif(btrim(p_price_area),'') is null
     or p_billing_month !~ '^\d{4}-\d{2}$' then
    raise exception using errcode='22023',message='spot_month_scope_invalid';
  end if;

  v_month_start_date := to_date(p_billing_month || '-01','YYYY-MM-DD');
  v_period_start := (v_month_start_date::timestamp at time zone 'Europe/Stockholm');
  v_period_end := ((v_month_start_date + interval '1 month')::timestamp at time zone 'Europe/Stockholm');
  v_expected_minutes := extract(epoch from (v_period_end-v_period_start))::bigint / 60;

  select
    count(*)::integer,
    coalesce(sum(d.expected_interval_count),0)::integer,
    count(*) filter (where d.status in ('verified','locked'))::integer
  into v_expected_days,v_expected_intervals,v_verified_days
  from public.spot_price_daily_summaries d
  where d.source=p_source
    and d.price_area=p_price_area
    and d.price_date>=v_month_start_date
    and d.price_date<(v_month_start_date + interval '1 month')::date;

  with clipped_intervals as (
    select
      interval_row.time_start,
      interval_row.time_end,
      interval_row.sek_per_kwh,
      extract(epoch from (
        least(interval_row.time_end,v_period_end)
        - greatest(interval_row.time_start,v_period_start)
      ))::numeric as covered_seconds
    from public.spot_price_intervals interval_row
    where interval_row.source=p_source
      and interval_row.price_area=p_price_area
      and interval_row.time_start<v_period_end
      and interval_row.time_end>v_period_start
  )
  select
    count(*)::integer,
    sum(i.sek_per_kwh * i.covered_seconds)
      / nullif(sum(i.covered_seconds), 0),
    min(i.sek_per_kwh),
    max(i.sek_per_kwh),
    coalesce(sum(i.covered_seconds)/60,0)::bigint,
    encode(
      digest(
        coalesce(string_agg(
          concat_ws('|',i.time_start::text,i.time_end::text,i.sek_per_kwh::text),
          '||' order by i.time_start,i.time_end
        ),''),
        'sha256'
      ),
      'hex'
    )
  into v_actual_intervals,v_avg,v_min,v_max,v_covered_minutes,v_checksum
  from clipped_intervals i;

  v_complete :=
    v_expected_days = extract(day from ((v_month_start_date + interval '1 month' - interval '1 day')::date))::integer
    and v_verified_days = v_expected_days
    and v_expected_intervals > 0
    and v_actual_intervals = v_expected_intervals
    and v_covered_minutes = v_expected_minutes;

  return query select
    v_period_start,
    v_period_end,
    v_avg,
    v_min,
    v_max,
    v_actual_intervals,
    v_expected_intervals,
    v_covered_minutes,
    v_expected_minutes,
    case when v_complete then '[]'::jsonb else jsonb_build_array(jsonb_build_object('code','incomplete_month_coverage')) end,
    v_now,
    case when v_complete then v_now else null end,
    case when v_complete then 'verified' else 'incomplete' end,
    v_checksum,
    v_now;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_contract_snapshot_to_quote_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_snapshot jsonb:=coalesce(new.snapshot_json,'{}'::jsonb);
  v_quote public.website_contract_quotes%rowtype;
  v_requires_quote boolean;
begin
  new.snapshot_schema_version:=coalesce(
    new.snapshot_schema_version,
    v_snapshot->>'snapshot_schema',
    v_snapshot->>'schema_version'
  );

  if new.snapshot_schema_version is distinct from 'gridex_contract_pricing_v6_selection' then
    return new;
  end if;

  new.quote_reference:=coalesce(
    new.quote_reference,v_snapshot->>'quote_reference'
  );
  new.quote_hash:=coalesce(new.quote_hash,v_snapshot->>'quote_hash');
  new.price_option_reference:=coalesce(
    new.price_option_reference,v_snapshot->>'price_option_reference'
  );
  new.area_price_reference:=coalesce(
    new.area_price_reference,v_snapshot->>'area_price_reference'
  );
  new.invoice_delivery_method:=coalesce(
    new.invoice_delivery_method,v_snapshot->>'invoice_delivery_method'
  );
  if new.selected_component_references='{}'::text[] then
    new.selected_component_references:=array(
      select value
      from jsonb_array_elements_text(
        coalesce(v_snapshot->'selected_component_references','[]'::jsonb)
      )
    );
  end if;
  v_requires_quote:=coalesce(new.source,'') in (
    'website_customer_applications',
    'external_website',
    'website_application'
  );
  if (v_requires_quote and new.quote_reference is null)
    or (v_requires_quote and new.quote_hash is null)
    or new.price_option_reference is null
    or new.invoice_delivery_method is null
    or (
      v_snapshot->>'contract_type'='fixed'
      and new.area_price_reference is null
    )
    or jsonb_typeof(new.base_price_components_snapshot)<>'array'
    or jsonb_typeof(new.price_components_snapshot)<>'array' then
    raise exception using
      errcode='23514',
      message='contract_commercial_snapshot_identity_incomplete';
  end if;

  if v_requires_quote then
    select quote.*
      into v_quote
    from public.website_contract_quotes quote
    where quote.company_id=new.company_id
      and quote.quote_reference=new.quote_reference;
    if not found
      or v_quote.quote_hash is distinct from new.quote_hash
      or v_quote.price_option_reference
        is distinct from new.price_option_reference
      or v_quote.area_price_reference is distinct from new.area_price_reference
      or v_quote.invoice_delivery_method
        is distinct from new.invoice_delivery_method
      or v_quote.selected_component_references
        is distinct from new.selected_component_references
      or v_quote.resolved_base_components
        is distinct from new.base_price_components_snapshot
      or v_quote.resolved_price_components
        is distinct from new.price_components_snapshot then
      raise exception using
        errcode='23514',
        message='contract_snapshot_quote_selection_mismatch';
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_locked_portfolio_settlement_to_underlay(p_actor_user_id uuid, p_company_id uuid, p_billing_underlay_id uuid, p_portfolio_monthly_settlement_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare v_underlay public.billing_underlays%rowtype; v_settlement public.portfolio_monthly_settlements%rowtype;
  v_snapshot jsonb; v_sha text; v_existing record;
begin
  if p_actor_user_id is null or not exists(select 1 from auth.users u where u.id=p_actor_user_id) then
    raise exception using errcode='42501',message='real_billing_actor_required';
  end if;
  if nullif(btrim(p_idempotency_key),'') is null then
    raise exception using errcode='22023',message='billing_settlement_idempotency_key_required';
  end if;
  select * into v_existing from public.portfolio_settlement_invoice_bindings
  where company_id=p_company_id and idempotency_key=p_idempotency_key;
  if found then return to_jsonb(v_existing); end if;
  select * into v_underlay from public.billing_underlays
  where id=p_billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found'; end if;
  select * into v_settlement from public.portfolio_monthly_settlements
  where id=p_portfolio_monthly_settlement_id and company_id=p_company_id
    and is_current and status in('final','locked') for update;
  if not found then raise exception using errcode='23514',message='final_or_locked_portfolio_settlement_required_for_billing'; end if;
  if v_settlement.price_area_code<>v_underlay.price_area
     or extract(year from v_settlement.delivery_month)::integer<>v_underlay.underlay_year
     or extract(month from v_settlement.delivery_month)::integer<>v_underlay.underlay_month
     or v_settlement.price_plan_version_id is distinct from v_underlay.price_plan_version_id then
    raise exception using errcode='23514',message='portfolio_settlement_underlay_scope_mismatch';
  end if;
  if not exists(
    select 1 from public.price_plan_versions v
    where v.id=v_settlement.price_plan_version_id and v.company_id=p_company_id
      and v.snapshot_json#>>'{portfolio_method,portfolio_id}'=v_settlement.portfolio_id::text
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_contract_method_mismatch';
  end if;
  if v_underlay.contract_id is null or not exists(
    select 1 from public.customer_contracts c
    where c.id=v_underlay.contract_id and c.company_id=p_company_id
      and c.status in('signed','active')
      and c.price_plan_version_id=v_settlement.price_plan_version_id
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_underlay_contract_mismatch';
  end if;
  if v_settlement.status='final' then
    perform set_config('gridex.portfolio_actor_user_id',p_actor_user_id::text,true);
    perform set_config('gridex.portfolio_audit_reason','locked by exact billing binding',true);
    update public.portfolio_monthly_settlements
    set status='locked',locked_by=p_actor_user_id,locked_at=now()
    where id=v_settlement.id;
    select * into v_settlement from public.portfolio_monthly_settlements
    where id=p_portfolio_monthly_settlement_id;
  end if;
  v_snapshot:=jsonb_build_object(
    'settlement_id',v_settlement.id,'company_id',v_settlement.company_id,
    'portfolio_id',v_settlement.portfolio_id,'price_plan_version_id',v_settlement.price_plan_version_id,
    'price_area_code',v_settlement.price_area_code,'delivery_month',v_settlement.delivery_month,
    'revision_no',v_settlement.revision_no,'status',v_settlement.status,
    'portfolio_price_ore_per_kwh',v_settlement.portfolio_price_ore_per_kwh,
    'management_fee_ore_per_kwh',v_settlement.management_fee_ore_per_kwh,
    'gross_energy_cost_sek',v_settlement.gross_energy_cost_sek,
    'hedging_result_sek',v_settlement.hedging_result_sek,
    'balancing_cost_sek',v_settlement.balancing_cost_sek,
    'other_allowed_cost_sek',v_settlement.other_allowed_cost_sek,
    'energy_volume_kwh',v_settlement.energy_volume_kwh,
    'calculation_snapshot_sha256',v_settlement.calculation_snapshot_sha256,'vat_rate',v_settlement.vat_rate,
    'vat_included',v_settlement.vat_included,
    'source',v_settlement.source,'locked_at',v_settlement.locked_at
  );
  v_sha:=encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');
  update public.billing_underlays set
    portfolio_id=v_settlement.portfolio_id,
    portfolio_monthly_settlement_id=v_settlement.id,
    portfolio_settlement_revision=v_settlement.revision_no,
    portfolio_settlement_sha256=v_sha,
    pricing_snapshot=coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object('portfolio_settlement',v_snapshot),
    updated_at=now()
  where id=v_underlay.id;
  insert into public.portfolio_settlement_invoice_bindings(
    company_id,billing_underlay_id,portfolio_monthly_settlement_id,
    settlement_snapshot,settlement_sha256,idempotency_key,bound_by
  ) values(
    p_company_id,v_underlay.id,v_settlement.id,v_snapshot,v_sha,btrim(p_idempotency_key),p_actor_user_id
  ) returning * into v_existing;
  return to_jsonb(v_existing);
end $function$

CREATE OR REPLACE FUNCTION public.gridex_create_invoice_export_graph_v1_core(p_run jsonb, p_items jsonb, p_invoices jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_company_id uuid:=nullif(p_run->>'company_id','')::uuid;
  v_run_id uuid:=coalesce(nullif(p_run->>'id','')::uuid,gen_random_uuid());
  v_idempotency_key text:=nullif(p_run->>'idempotency_key','');
  v_existing_id uuid;
  v_item jsonb;
  v_invoice jsonb;
  v_underlay public.billing_underlays%rowtype;
  v_export_item_id uuid;
  v_count integer:=0;
begin
  if auth.role()<>'service_role' then
    raise exception using errcode='42501',message='invoice_export_graph_service_role_required';
  end if;
  if v_company_id is null or v_idempotency_key is null then
    raise exception using errcode='22023',message='invoice_export_company_idempotency_required';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array'
     or jsonb_typeof(coalesce(p_invoices,'[]'::jsonb))<>'array'
     or jsonb_array_length(coalesce(p_items,'[]'::jsonb))<>jsonb_array_length(coalesce(p_invoices,'[]'::jsonb)) then
    raise exception using errcode='22023',message='invoice_export_graph_array_mismatch';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text||':'||v_idempotency_key,0));
  select id into v_existing_id from public.invoice_export_runs where company_id=v_company_id and idempotency_key=v_idempotency_key;
  if v_existing_id is not null then return jsonb_build_object('run_id',v_existing_id,'existing',true); end if;

  insert into public.invoice_export_runs(
    id,company_id,provider,environment,billing_month,financing_mode,status,total_items,readiness_snapshot,metadata,requested_by,idempotency_key
  ) values (
    v_run_id,v_company_id,coalesce(nullif(p_run->>'provider',''),'capway_aptic'),coalesce(nullif(p_run->>'environment',''),'test'),p_run->>'billing_month',
    coalesce(nullif(p_run->>'financing_mode',''),'invoice_service'),'draft',jsonb_array_length(p_items),coalesce(p_run->'readiness_snapshot','{}'::jsonb),
    coalesce(p_run->'metadata','{}'::jsonb),nullif(p_run->>'requested_by','')::uuid,v_idempotency_key
  );

  for v_item,v_invoice in
    select i.value,n.value from jsonb_array_elements(p_items) with ordinality i(value,ordinality)
    join jsonb_array_elements(p_invoices) with ordinality n(value,ordinality) using(ordinality)
  loop
    v_export_item_id:=nullif(v_item->>'id','')::uuid;
    select * into v_underlay from public.billing_underlays
    where id=nullif(v_item->>'billing_underlay_id','')::uuid and company_id=v_company_id for share;
    if not found
       or v_underlay.customer_id is distinct from nullif(v_item->>'customer_id','')::uuid
       or coalesce(v_underlay.customer_contract_id,v_underlay.contract_id) is distinct from nullif(v_item->>'customer_contract_id','')::uuid then
      raise exception using errcode='23514',message='invoice_export_underlay_customer_contract_mismatch';
    end if;

    insert into public.invoice_export_items(
      id,company_id,export_run_id,customer_id,billing_underlay_id,pricing_run_id,customer_contract_id,metering_point_id,period_start,period_end,total_kwh,currency,
      provider,environment,status,financing_mode,amount_ex_vat,vat_amount,amount_inc_vat,idempotency_key,metadata
    ) values (
      v_export_item_id,v_company_id,v_run_id,nullif(v_item->>'customer_id','')::uuid,v_underlay.id,nullif(v_item->>'pricing_run_id','')::uuid,
      nullif(v_item->>'customer_contract_id','')::uuid,nullif(v_item->>'metering_point_id','')::uuid,nullif(v_item->>'period_start','')::date,nullif(v_item->>'period_end','')::date,
      nullif(v_item->>'total_kwh','')::numeric,coalesce(nullif(v_item->>'currency',''),'SEK'),coalesce(nullif(v_item->>'provider',''),'capway_aptic'),
      coalesce(nullif(v_item->>'environment',''),'test'),'pending',coalesce(nullif(v_item->>'financing_mode',''),'invoice_service'),
      coalesce(nullif(v_item->>'amount_ex_vat','')::numeric,0),coalesce(nullif(v_item->>'vat_amount','')::numeric,0),coalesce(nullif(v_item->>'amount_inc_vat','')::numeric,0),
      nullif(v_item->>'idempotency_key',''),coalesce(v_item->'metadata','{}'::jsonb)
    );

    if nullif(v_invoice->>'invoice_export_item_id','')::uuid is distinct from v_export_item_id
       or nullif(v_invoice->>'customer_id','')::uuid is distinct from v_underlay.customer_id
       or nullif(v_invoice->>'customer_contract_id','')::uuid is distinct from coalesce(v_underlay.customer_contract_id,v_underlay.contract_id) then
      raise exception using errcode='23514',message='customer_invoice_export_identity_mismatch';
    end if;

    insert into public.customer_invoices(
      company_id,customer_id,contract_id,customer_contract_id,billing_underlay_id,partner_export_id,partner_invoice_reference,invoice_reference,
      invoice_export_item_id,canonical_export_item_id,period_start,period_end,total_kwh,amount_ex_vat,vat_amount,amount_inc_vat,currency,status,source_system,metadata,updated_at
    ) values (
      v_company_id,v_underlay.customer_id,coalesce(v_underlay.customer_contract_id,v_underlay.contract_id),coalesce(v_underlay.customer_contract_id,v_underlay.contract_id),
      v_underlay.id,null,
      coalesce(nullif(v_invoice->>'partner_invoice_reference',''),'pending:'||v_export_item_id::text),
      coalesce(nullif(v_invoice->>'invoice_reference',''),'draft:'||v_export_item_id::text),
      v_export_item_id,v_export_item_id,nullif(v_invoice->>'period_start','')::date,nullif(v_invoice->>'period_end','')::date,nullif(v_invoice->>'total_kwh','')::numeric,
      coalesce(nullif(v_invoice->>'amount_ex_vat','')::numeric,0),coalesce(nullif(v_invoice->>'vat_amount','')::numeric,0),coalesce(nullif(v_invoice->>'amount_inc_vat','')::numeric,0),
      coalesce(nullif(v_invoice->>'currency',''),'SEK'),'draft','canonical_invoice_export',coalesce(v_invoice->'metadata','{}'::jsonb),now()
    );
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object('run_id',v_run_id,'existing',false,'item_count',v_count);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_invoice_review_draft_v1(p_company_id uuid, p_run jsonb, p_items jsonb, p_invoices jsonb, p_enrichment jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_result jsonb;
  v_item_id uuid := nullif(p_enrichment->>'invoice_export_item_id', '')::uuid;
  v_invoice_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'invoice_review_draft_service_role_required';
  end if;
  if p_company_id is null or v_item_id is null
     or nullif(p_run->>'company_id', '')::uuid is distinct from p_company_id then
    raise exception using errcode = '22023', message = 'invoice_review_draft_payload_invalid';
  end if;

  v_result := public.gridex_create_invoice_export_graph_v1(p_run, p_items, p_invoices);

  update public.customer_invoices
  set price_plan_version_id = nullif(p_enrichment->>'price_plan_version_id', '')::uuid,
      price_area_code = nullif(p_enrichment->>'price_area_code', ''),
      consumption_kwh = nullif(p_enrichment->>'consumption_kwh', '')::numeric,
      vat_rate = nullif(p_enrichment->>'vat_rate', '')::numeric,
      calculation_snapshot = p_enrichment->'calculation_snapshot',
      calculation_snapshot_sha256 = nullif(p_enrichment->>'calculation_snapshot_sha256', ''),
      metadata = coalesce(p_enrichment->'metadata', metadata),
      updated_at = now()
  where company_id = p_company_id
    and invoice_export_item_id = v_item_id
  returning id into v_invoice_id;
  if v_invoice_id is null then
    raise exception using errcode = 'P0002', message = 'invoice_review_draft_invoice_missing';
  end if;

  return v_result || jsonb_build_object('invoice_id', v_invoice_id);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_contract_price_snapshot_hash_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_expected_hash text;
begin
  if new.snapshot_json is null then
    raise exception using
      errcode = '23502',
      message = 'contract_price_snapshot_json_required';
  end if;

  v_expected_hash := encode(
    extensions.digest(convert_to(new.snapshot_json::text, 'UTF8'), 'sha256'),
    'hex'
  );

  if nullif(btrim(coalesce(new.snapshot_hash, '')), '') is not null
     and lower(btrim(new.snapshot_hash)) is distinct from v_expected_hash then
    raise exception using
      errcode = '23514',
      message = 'contract_price_snapshot_hash_mismatch';
  end if;

  new.snapshot_hash := v_expected_hash;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_quote_binding_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_quote public.website_contract_quotes%rowtype;
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_quote_reference text:=nullif(v_row->>'quote_reference','');
  v_text text;
begin
  if v_quote_reference is null then return new; end if;

  select * into v_quote
  from public.website_contract_quotes q
  where q.company_id=v_company_id
    and q.quote_reference=v_quote_reference;
  if not found then
    raise exception using errcode='23503',message='quote_binding_not_found_for_tenant';
  end if;

  foreach v_text in array array[
    nullif(v_row->>'contract_product_id',''),
    nullif(v_row->>'contract_product_version_id',''),
    nullif(v_row->>'contract_publication_version_id',''),
    nullif(v_row->>'price_plan_id',''),
    nullif(v_row->>'price_plan_version_id',''),
    nullif(v_row->>'price_book_id',''),
    nullif(v_row->>'legal_bundle_version_id',''),
    nullif(v_row->>'energy_direction','')
  ] loop
    if v_text is null then
      raise exception using errcode='23502',message='quote_binding_target_identity_incomplete';
    end if;
  end loop;

  if v_quote.contract_product_id is distinct from (v_row->>'contract_product_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_product_mismatch';
  end if;
  if v_quote.contract_product_version_id is distinct from (v_row->>'contract_product_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_version_mismatch';
  end if;
  if v_quote.contract_publication_version_id is distinct from (v_row->>'contract_publication_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_publication_version_mismatch';
  end if;
  if v_quote.price_plan_id is distinct from (v_row->>'price_plan_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_mismatch';
  end if;
  if v_quote.price_plan_version_id is distinct from (v_row->>'price_plan_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_version_mismatch';
  end if;
  if v_quote.price_book_id is distinct from (v_row->>'price_book_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_book_mismatch';
  end if;
  if v_quote.legal_bundle_version_id is distinct from (v_row->>'legal_bundle_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_legal_bundle_mismatch';
  end if;
  if v_quote.energy_direction is distinct from (v_row->>'energy_direction') then
    raise exception using errcode='23514',message='quote_binding_energy_direction_mismatch';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_quote_canonical_identity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_publication public.contract_publication_versions%rowtype;
  v_product_version public.contract_product_versions%rowtype;
  v_product_company_id uuid;
  v_publication_company_id uuid;
  v_price_plan_company_id uuid;
  v_price_book_company_id uuid;
  v_legal_company_id uuid;
begin
  if new.contract_product_id is null
     or new.contract_product_version_id is null
     or new.contract_publication_version_id is null
     or new.price_plan_id is null
     or new.price_plan_version_id is null
     or new.price_book_id is null
     or new.legal_bundle_version_id is null
     or new.energy_direction is null then
    raise exception using errcode='23502',message='quote_canonical_identity_incomplete';
  end if;

  select * into v_publication
  from public.contract_publication_versions
  where id=new.contract_publication_version_id;
  if not found then
    raise exception using errcode='23503',message='quote_publication_version_not_found';
  end if;

  select * into v_product_version
  from public.contract_product_versions
  where id=new.contract_product_version_id;
  if not found then
    raise exception using errcode='23503',message='quote_product_version_not_found';
  end if;

  select company_id into v_product_company_id
  from public.contract_products
  where id=new.contract_product_id;
  if v_product_company_id is not null and v_product_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_contract_product_tenant_mismatch';
  end if;

  select assignment.company_id into v_publication_company_id
  from public.contract_publications publication
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  where publication.id=v_publication.contract_publication_id;
  if v_publication_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_publication_tenant_mismatch';
  end if;

  select company_id into v_price_plan_company_id
  from public.price_plans
  where id=new.price_plan_id;
  if v_price_plan_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_price_plan_tenant_mismatch';
  end if;

  select company_id into v_price_book_company_id
  from public.price_books
  where id=new.price_book_id;
  if v_price_book_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_price_book_tenant_mismatch';
  end if;

  select company_id into v_legal_company_id
  from public.legal_bundle_versions
  where id=new.legal_bundle_version_id;
  if v_legal_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_legal_bundle_tenant_mismatch';
  end if;

  if v_product_version.contract_product_id is distinct from new.contract_product_id
     or v_publication.contract_product_version_id is distinct from new.contract_product_version_id
     or v_publication.price_plan_id is distinct from new.price_plan_id
     or v_publication.price_plan_version_id is distinct from new.price_plan_version_id
     or v_publication.price_book_id is distinct from new.price_book_id
     or v_publication.legal_bundle_version_id is distinct from new.legal_bundle_version_id
     or v_publication.offer_reference is distinct from new.offer_reference
     or v_publication.customer_type not in (new.customer_type,'both')
     or v_product_version.energy_direction is distinct from new.energy_direction
     or v_publication.energy_direction is distinct from new.energy_direction then
    raise exception using errcode='23514',message='quote_canonical_identity_mismatch';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_spot_price_month_server_aggregate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_calc record;
begin
  if tg_op='UPDATE' then
    if old.status='locked' then
      return new;
    end if;

    -- Locking/annotation-only updates must be persisted verbatim.
    if (to_jsonb(new) - array['status','locked_at','locked_by','lock_reason','updated_at'])
       = (to_jsonb(old) - array['status','locked_at','locked_by','lock_reason','updated_at'])
       and (
         new.status is distinct from old.status
         or new.locked_at is distinct from old.locked_at
         or new.locked_by is distinct from old.locked_by
         or new.lock_reason is distinct from old.lock_reason
       ) then
      return new;
    end if;
  end if;

  -- Canonicalize aggregate fields in NEW instead of replacing/cancelling the row operation.
  select * into strict v_calc
  from private.gridex_calculate_spot_price_month_v1(new.source,new.price_area,new.billing_month);

  new.period_start := v_calc.period_start;
  new.period_end := v_calc.period_end;
  new.average_sek_per_kwh := v_calc.average_sek_per_kwh;
  new.min_sek_per_kwh := v_calc.min_sek_per_kwh;
  new.max_sek_per_kwh := v_calc.max_sek_per_kwh;
  new.interval_count := v_calc.interval_count;
  new.expected_interval_count := v_calc.expected_interval_count;
  new.covered_duration_minutes := v_calc.covered_duration_minutes;
  new.expected_duration_minutes := v_calc.expected_duration_minutes;
  new.quality_issues := v_calc.quality_issues;
  new.provider_fetched_at := v_calc.provider_fetched_at;
  new.verified_at := v_calc.verified_at;
  new.status := v_calc.status;
  new.source_checksum := v_calc.source_checksum;
  new.updated_at := v_calc.updated_at;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_guard_portfolio_settlement_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op='DELETE' then raise exception using errcode='55000',message='portfolio_settlement_append_only'; end if;
  if old.status<>new.status and not (
    (old.status='draft' and new.status='calculated')
    or (old.status='calculated' and new.status='reviewed')
    or (old.status='reviewed' and new.status='final')
    or (old.status='final' and new.status='locked')
  ) then
    raise exception using errcode='23514',message='invalid_portfolio_settlement_transition';
  end if;
  if new.status in('final','locked') and (
    new.portfolio_price_ore_per_kwh is null
    or new.calculation_snapshot_sha256 is null
    or new.calculated_at is null or new.reviewed_at is null or new.approved_at is null
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_final_evidence_incomplete';
  end if;
  if old.status='locked' and not (
    coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
    and new.is_current=false and new.superseded_by_settlement_id is not null
    and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')=(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
  ) then
    raise exception using errcode='55000',message='locked_portfolio_settlement_immutable';
  end if;
  if old.status='final' and not (
    (
      new.status='locked'
      and (to_jsonb(new)-'status'-'locked_by'-'locked_at')
        =(to_jsonb(old)-'status'-'locked_by'-'locked_at')
    ) or (
      coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
      and new.status='final' and new.is_current=false
      and new.superseded_by_settlement_id is not null
      and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')
        =(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
    )
  ) then
    raise exception using errcode='55000',message='final_portfolio_settlement_immutable_create_correction_revision';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_lock_pricing_run(p_company_id uuid, p_pricing_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_run public.pricing_runs%rowtype;
  v_underlay public.billing_underlays%rowtype;
  v_month text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_pricing_run_id::text,0));
  select * into v_run from public.pricing_runs where id=p_pricing_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='pricing_run_not_found_for_tenant'; end if;
  if v_run.status not in ('success','locked') then raise exception using errcode='23514',message='only_successful_pricing_run_can_be_locked'; end if;
  select * into v_underlay from public.billing_underlays where id=v_run.billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='pricing_underlay_not_found'; end if;
  v_month:=to_char(v_run.billing_period_start at time zone 'Europe/Stockholm','YYYY-MM');
  if v_run.status='locked' then
    return jsonb_build_object('pricing_run_id',v_run.id,'billing_underlay_id',v_underlay.id,'billing_month',v_month,'status','locked');
  end if;

  insert into public.price_period_locks(company_id,billing_month,lock_scope,status,locked_by,locked_at)
  values(p_company_id,v_month,'pricing_preview','locked',p_actor_user_id,now())
  on conflict(company_id,billing_month,lock_scope) do update set status='locked',locked_by=excluded.locked_by,locked_at=excluded.locked_at;

  insert into public.contract_charge_ledger(
    company_id,customer_contract_id,component_key,event_key,pricing_run_id,amount_ex_vat,metadata
  )
  select p_company_id,v_underlay.contract_id,
    coalesce(nullif(l.metadata->>'component_key',''),l.line_type||':'||encode(digest(lower(l.description),'sha256'),'hex')),
    case
      when coalesce(l.metadata->>'lifecycle','')='event_only' then coalesce(nullif(l.metadata->>'billing_event_id',''),nullif(l.metadata->>'event',''),'event')
      else 'contract'
    end,v_run.id,l.amount_ex_vat,l.metadata
  from public.pricing_preview_lines l
  where l.pricing_run_id=v_run.id
    and coalesce(l.metadata->>'lifecycle','') in ('once_per_contract','one_time','event_only')
  on conflict(customer_contract_id,component_key,event_key) do nothing;

  update public.pricing_runs set status='locked',locked_at=now() where id=v_run.id;
  update public.billing_underlays set readiness_status='ready',updated_at=now()
  where id=v_underlay.id and company_id=p_company_id;
  return jsonb_build_object('pricing_run_id',v_run.id,'billing_underlay_id',v_underlay.id,'billing_month',v_month,'status','locked');
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_lock_spot_price_month(p_provider text, p_price_area text, p_billing_month text, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.spot_price_monthly_summaries%rowtype;
  v_now timestamptz:=now();
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'spot_settlement_lock_service_role_required' using errcode='42501';
  end if;
  if upper(coalesce(p_price_area,'')) not in ('SE1','SE2','SE3','SE4')
     or coalesce(p_billing_month,'') !~ '^\d{4}-\d{2}$' then
    raise exception 'invalid_spot_settlement_period' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(trim(p_provider))||':'||upper(trim(p_price_area))||':'||p_billing_month,0));
  select * into v_row
  from public.spot_price_monthly_summaries s
  where s.source=lower(trim(p_provider))
    and s.price_area=upper(trim(p_price_area))
    and s.billing_month=p_billing_month
  for update;
  if not found then raise exception 'market_price_unavailable' using errcode='P0002'; end if;
  if v_row.status not in ('verified','locked') or v_row.verified_at is null
     or v_row.period_start is null or v_row.period_end is null or v_row.period_end<=v_row.period_start
     or v_row.covered_duration_minutes is null or v_row.expected_duration_minutes is null
     or v_row.covered_duration_minutes is distinct from v_row.expected_duration_minutes
     or (case
           when jsonb_typeof(v_row.quality_issues) = 'array'
             then jsonb_array_length(v_row.quality_issues)
           else 1
         end) > 0
     or nullif(btrim(v_row.source_checksum),'') is null
     or (v_row.status='locked' and (v_row.locked_at is null or v_row.locked_at<v_row.verified_at)) then
    raise exception 'market_price_incomplete' using errcode='23514';
  end if;
  if v_row.status='locked' then return to_jsonb(v_row); end if;
  update public.spot_price_monthly_summaries
  set status='locked',locked_at=v_now,locked_by=p_actor_user_id,lock_reason=nullif(btrim(p_reason),''),updated_at=v_now
  where id=v_row.id
  returning * into v_row;
  insert into public.canonical_energy_flow_events(event_type,source,payload,actor_type,actor_id)
  values('market_price.period.locked','spot_settlement_lock',jsonb_build_object(
    'summary_id',v_row.id,'provider',v_row.source,'price_area',v_row.price_area,
    'billing_month',v_row.billing_month,'source_checksum',v_row.source_checksum,
    'locked_at',v_row.locked_at,'reason',v_row.lock_reason
  ),case when p_actor_user_id is null then 'system' else 'user' end,p_actor_user_id);
  return to_jsonb(v_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_persist_pricing_run(p_company_id uuid, p_billing_underlay_id uuid, p_result jsonb, p_pricing_snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_underlay public.billing_underlays%rowtype;
  v_run_id uuid;
  v_final_status text:=coalesce(nullif(p_result->>'status',''),'failed');
  v_rows integer;
begin
  if p_company_id is null or p_billing_underlay_id is null then
    raise exception using errcode='22023',message='company_and_billing_underlay_required';
  end if;
  if v_final_status not in ('success','failed','needs_review') then
    raise exception using errcode='22023',message='invalid_pricing_result_status';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_billing_underlay_id::text,0));
  select * into v_underlay from public.billing_underlays
  where id=p_billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found_for_tenant'; end if;
  if v_underlay.contract_id is null or coalesce(v_underlay.contract_price_snapshot_id,v_underlay.pricing_snapshot_id) is null then
    raise exception using errcode='23514',message='exact_contract_and_price_snapshot_required';
  end if;
  if exists(select 1 from public.pricing_runs where company_id=p_company_id and billing_underlay_id=p_billing_underlay_id and status='locked') then
    raise exception using errcode='55000',message='pricing_run_locked';
  end if;

  insert into public.pricing_runs(
    company_id,billing_underlay_id,customer_id,billing_period_start,billing_period_end,status,
    total_ex_vat,vat_amount,total_inc_vat,warnings,errors,metadata
  ) values (
    p_company_id,p_billing_underlay_id,v_underlay.customer_id,v_underlay.billing_period_start,v_underlay.billing_period_end,
    case when v_final_status='success' then 'needs_review' else v_final_status end,
    coalesce((p_result->>'total_ex_vat')::numeric,0),coalesce((p_result->>'vat_amount')::numeric,0),
    coalesce((p_result->>'total_inc_vat')::numeric,0),coalesce(p_result->'warnings','[]'::jsonb),
    coalesce(p_result->'errors','[]'::jsonb),jsonb_build_object('source','pricing_core','atomic',true)
  ) returning id into v_run_id;

  insert into public.pricing_preview_lines(
    company_id,pricing_run_id,billing_underlay_id,line_type,description,quantity,unit,
    unit_price_ex_vat,amount_ex_vat,vat_rate,vat_amount,amount_inc_vat,sort_order,metadata
  )
  select p_company_id,v_run_id,p_billing_underlay_id,
    coalesce(nullif(x->>'line_type',''),'unknown'),coalesce(nullif(x->>'description',''),'Prisrad'),
    nullif(x->>'quantity','')::numeric,coalesce(nullif(x->>'unit',''),'st'),nullif(x->>'unit_price_ex_vat','')::numeric,
    coalesce(nullif(x->>'amount_ex_vat','')::numeric,0),coalesce(nullif(x->>'vat_rate','')::numeric,0),
    coalesce(nullif(x->>'vat_amount','')::numeric,0),coalesce(nullif(x->>'amount_inc_vat','')::numeric,0),
    coalesce(nullif(x->>'sort_order','')::integer,100),coalesce(x->'metadata','{}'::jsonb)
  from jsonb_array_elements(coalesce(p_result->'lines','[]'::jsonb)) x;

  insert into public.pricing_interval_evidence(
    company_id,pricing_run_id,billing_underlay_id,billing_underlay_item_id,customer_contract_id,
    metering_interval_start,metering_interval_end,resolution,consumption_kwh,price_sek_per_kwh,
    amount_ex_vat,price_source_id,price_area,evidence_sha256
  )
  select p_company_id,v_run_id,p_billing_underlay_id,nullif(x->>'billing_underlay_item_id','')::uuid,
    v_underlay.contract_id,(x->>'metering_interval_start')::timestamptz,(x->>'metering_interval_end')::timestamptz,
    x->>'resolution',(x->>'consumption_kwh')::numeric,(x->>'price_sek_per_kwh')::numeric,
    (x->>'amount_ex_vat')::numeric,nullif(x->>'price_source_id','')::uuid,x->>'price_area',
    encode(digest((x||jsonb_build_object('pricing_run_id',v_run_id))::text,'sha256'),'hex')
  from jsonb_array_elements(coalesce(p_result->'interval_evidence','[]'::jsonb)) x;

  if v_final_status='success' then
    update public.pricing_runs set status='superseded'
    where company_id=p_company_id and billing_underlay_id=p_billing_underlay_id and id<>v_run_id and status='success';
    update public.pricing_runs set status='success' where id=v_run_id;
    update public.billing_underlays set
      status='validated',readiness_status='ready',readiness_issues='[]'::jsonb,
      invoice_readiness_status='ready_for_invoice',invoice_readiness_issues='[]'::jsonb,
      calculated_total_sek_ex_vat=coalesce((p_result->>'total_ex_vat')::numeric,0),
      calculated_vat_sek=coalesce((p_result->>'vat_amount')::numeric,0),
      calculated_total_sek_inc_vat=coalesce((p_result->>'total_inc_vat')::numeric,0),
      pricing_snapshot=coalesce(p_pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_pricing_run_id',v_run_id,'latest_pricing_warnings',coalesce(p_result->'warnings','[]'::jsonb),
        'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ),updated_at=now()
    where id=p_billing_underlay_id and company_id=p_company_id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then raise exception using errcode='P0002',message='billing_underlay_atomic_update_failed'; end if;
  else
    update public.billing_underlays set
      pricing_snapshot=coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_failed_pricing_run_id',v_run_id,'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ),updated_at=now()
    where id=p_billing_underlay_id and company_id=p_company_id;
  end if;
  return v_run_id;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_publish_contract_publication_version(p_publication_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS contract_publication_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare v_row public.contract_publication_versions; v_blockers text[]; v_company uuid; v_product uuid;
begin
  select r.blockers,r.company_id,pv.contract_product_id into v_blockers,v_company,v_product
  from public.contract_publication_readiness_v r
  join public.contract_publication_versions x on x.id=r.contract_publication_version_id
  join public.contract_product_versions pv on pv.id=x.contract_product_version_id
  where r.contract_publication_version_id=p_publication_version_id;
  if not found then raise exception 'publication_version_not_found'; end if;
  if coalesce(array_length(v_blockers,1),0)>0 then raise exception 'publication_not_ready:%',array_to_string(v_blockers,','); end if;
  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions oldv set status='ended'
  from public.contract_product_versions oldpv
  where oldv.contract_product_version_id=oldpv.id and oldpv.contract_product_id=v_product and oldv.id<>p_publication_version_id and oldv.status='published';
  update public.tenant_contract_channels ch set status='ended',updated_at=now()
  from public.tenant_contract_assignments ta join public.contract_product_versions oldpv on oldpv.id=ta.contract_product_version_id
  where ch.assignment_id=ta.id and ta.company_id=v_company and oldpv.contract_product_id=v_product and ch.channel='website' and ch.status='active';
  update public.contract_publications p set status='ended',updated_at=now()
  from public.tenant_contract_assignments ta join public.contract_product_versions oldpv on oldpv.id=ta.contract_product_version_id
  where p.assignment_id=ta.id and ta.company_id=v_company and oldpv.contract_product_id=v_product and p.channel='website' and p.status='published';
  update public.contract_publication_versions cpv set status='published',published_at=coalesce(cpv.published_at,now()),locked_at=coalesce(cpv.locked_at,now()),offer_reference=coalesce(cpv.offer_reference,'offer_'||encode(gen_random_bytes(20),'hex'))
  where cpv.id=p_publication_version_id returning * into v_row;
  update public.contract_publications set status='published',updated_at=now() where id=v_row.contract_publication_id;
  update public.tenant_contract_channels ch set status='active',updated_at=now() from public.contract_publications p where p.id=v_row.contract_publication_id and ch.assignment_id=p.assignment_id and ch.channel='website';
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean DEFAULT false, p_fallback_reason text DEFAULT NULL::text, p_source_summary_ids uuid[] DEFAULT '{}'::uuid[], p_source_checksum text DEFAULT NULL::text, p_source_resolution text DEFAULT 'daily'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_active public.market_price_previews%rowtype;
  v_id uuid;
  v_provider text := lower(trim(p_provider));
  v_area text := upper(trim(p_price_area));
  v_now timestamptz := now();
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'market_preview_publish_service_role_required' using errcode='42501';
  end if;
  if v_area not in ('SE1','SE2','SE3','SE4')
     or p_reference_period not in ('latest_complete_day','rolling_7_days','rolling_30_days','month_to_date','forecast')
     or p_period_end < p_period_start
     or p_source_as_of is null
     or p_generated_at is null
     or p_stale_after <= p_generated_at
     or p_price_sek_per_kwh is null
     or p_requested_days is null or p_requested_days <= 0
     or p_included_days is null or p_included_days <= 0 or p_included_days > p_requested_days then
    raise exception 'invalid_market_preview' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_provider||':'||v_area||':'||p_reference_period,0)
  );

  select * into v_active
  from public.market_price_previews m
  where m.provider = v_provider
    and m.price_area = v_area
    and m.reference_period = p_reference_period
    and m.status = 'active'
  for update;

  if found
     and v_active.source_checksum is not distinct from p_source_checksum
     and v_active.source_as_of is not distinct from p_source_as_of
     and v_active.price_sek_per_kwh is not distinct from p_price_sek_per_kwh
     and v_active.period_start = p_period_start
     and v_active.period_end = p_period_end
     and v_active.requested_days is not distinct from p_requested_days
     and v_active.included_days is not distinct from p_included_days
     and v_active.fallback_used is not distinct from coalesce(p_fallback_used,false)
     and v_active.fallback_reason is not distinct from nullif(btrim(p_fallback_reason),'') then
    return jsonb_build_object(
      'created', false,
      'unchanged', true,
      'preview_id', v_active.id,
      'source_checksum', v_active.source_checksum
    );
  end if;

  update public.market_price_previews
  set status='superseded', updated_at=v_now
  where provider=v_provider
    and price_area=v_area
    and reference_period=p_reference_period
    and status='active';

  insert into public.market_price_previews(
    provider,price_area,reference_period,period_start,period_end,
    as_of,source_as_of,generated_at,price_sek_per_kwh,stale_after,
    requested_days,included_days,status,fallback_used,fallback_reason,
    source_summary_ids,source_checksum,source_resolution,metadata,updated_at
  ) values (
    v_provider,v_area,p_reference_period,p_period_start,p_period_end,
    p_source_as_of,p_source_as_of,p_generated_at,p_price_sek_per_kwh,p_stale_after,
    p_requested_days,p_included_days,'active',coalesce(p_fallback_used,false),
    nullif(btrim(p_fallback_reason),''),coalesce(p_source_summary_ids,'{}'::uuid[]),
    p_source_checksum,coalesce(nullif(btrim(p_source_resolution),''),'daily'),
    coalesce(p_metadata,'{}'::jsonb),v_now
  ) returning id into v_id;

  return jsonb_build_object(
    'created', true,
    'unchanged', false,
    'preview_id', v_id,
    'source_checksum', p_source_checksum
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_record_invoice_purchase_request_v1(p_company_id uuid, p_invoice_export_item_id uuid, p_financing_mode text, p_payload jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_event_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'invoice_purchase_service_role_required';
  end if;
  if p_company_id is null or p_invoice_export_item_id is null
     or p_financing_mode not in ('factoring_without_recourse', 'factoring_with_recourse') then
    raise exception using errcode = '22023', message = 'invoice_purchase_payload_invalid';
  end if;

  update public.invoice_export_items
  set purchase_status = 'requested',
      financing_mode = p_financing_mode,
      updated_at = now()
  where id = p_invoice_export_item_id and company_id = p_company_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'invoice_export_item_not_found_for_tenant';
  end if;

  insert into public.invoice_purchase_events (
    company_id, invoice_export_item_id, event_type, purchase_status, finance_status, payload, created_by
  ) values (
    p_company_id, p_invoice_export_item_id, 'purchase_requested_manual', 'requested', p_financing_mode,
    coalesce(p_payload, '{}'::jsonb), p_actor_user_id
  )
  returning id into v_event_id;

  return jsonb_build_object('event_id', v_event_id);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_set_billing_period_lock_v1(p_company_id uuid, p_billing_month text, p_locked boolean, p_status text, p_actor_user_id uuid, p_reason text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := now();
  v_year integer;
  v_month integer;
  v_status text := case when p_locked then coalesce(nullif(p_status, ''), 'locked') else 'reopened' end;
  v_lock public.billing_period_locks%rowtype;
  v_unlocked_runs integer := 0;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'billing_period_lock_service_role_required';
  end if;
  if p_company_id is null or p_locked is null or p_billing_month !~ '^\d{4}-(0[1-9]|1[0-2])$'
     or (p_locked and v_status not in ('locked', 'exported', 'closed')) then
    raise exception using errcode = '22023', message = 'billing_period_lock_payload_invalid';
  end if;
  v_year := split_part(p_billing_month, '-', 1)::integer;
  v_month := split_part(p_billing_month, '-', 2)::integer;

  if p_locked then
    insert into public.billing_period_locks (
      company_id, billing_year, billing_month, status, locked_by, locked_at, unlocked_by, unlocked_at,
      lock_reason, metadata, updated_at
    ) values (
      p_company_id, v_year, v_month, v_status, p_actor_user_id, v_now, null, null,
      coalesce(p_reason, 'Fakturaperioden är låst.'), coalesce(p_metadata, '{}'::jsonb), v_now
    )
    on conflict (company_id, billing_year, billing_month) do update set
      status = excluded.status, locked_by = excluded.locked_by, locked_at = excluded.locked_at,
      unlocked_by = null, unlocked_at = null, lock_reason = excluded.lock_reason,
      metadata = excluded.metadata, updated_at = excluded.updated_at
    returning * into v_lock;

    insert into public.price_period_locks (
      company_id, billing_month, lock_scope, status, locked_by, locked_at, reason, metadata
    ) values (
      p_company_id, p_billing_month, 'billing_period', 'locked', p_actor_user_id, v_now,
      coalesce(p_reason, 'Fakturaperioden är låst.'), coalesce(p_metadata, '{}'::jsonb)
    )
    on conflict (company_id, billing_month, lock_scope) do update set
      status = 'locked', locked_by = excluded.locked_by, locked_at = excluded.locked_at,
      reason = excluded.reason, metadata = excluded.metadata;
  else
    insert into public.billing_period_locks (
      company_id, billing_year, billing_month, status, unlocked_by, unlocked_at, lock_reason, updated_at
    ) values (
      p_company_id, v_year, v_month, 'reopened', p_actor_user_id, v_now,
      coalesce(p_reason, 'Fakturaperioden har låsts upp.'), v_now
    )
    on conflict (company_id, billing_year, billing_month) do update set
      status = 'reopened', unlocked_by = excluded.unlocked_by, unlocked_at = excluded.unlocked_at,
      lock_reason = excluded.lock_reason, updated_at = excluded.updated_at
    returning * into v_lock;

    update public.price_period_locks
    set status = 'unlocked', reason = coalesce(p_reason, 'Fakturaperioden har låsts upp.')
    where company_id = p_company_id
      and billing_month = p_billing_month
      and lock_scope in ('billing_period', 'invoice_export');

    v_unlocked_runs := public.gridex_unlock_pricing_runs_for_month(
      p_company_id, p_billing_month, p_actor_user_id, coalesce(p_reason, 'billing_period_unlocked'));
  end if;

  return jsonb_build_object('lock', to_jsonb(v_lock), 'unlocked_pricing_runs', coalesce(v_unlocked_runs, 0));
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_store_billing_underlay(p_company_id uuid, p_underlay jsonb, p_items jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_id uuid;
  v_customer_id uuid := nullif(p_underlay->>'customer_id','')::uuid;
  v_metering_point_id uuid := nullif(p_underlay->>'metering_point_id','')::uuid;
  v_year integer := (p_underlay->>'underlay_year')::integer;
  v_month integer := (p_underlay->>'underlay_month')::integer;
  v_start_instant timestamptz := (p_underlay->>'billing_period_start')::timestamptz;
  v_end_instant timestamptz := (p_underlay->>'billing_period_end')::timestamptz;
  v_start_date date := (v_start_instant at time zone 'Europe/Stockholm')::date;
  v_end_date date := (v_end_instant at time zone 'Europe/Stockholm')::date;
  v_energy_direction text := coalesce(nullif(p_underlay->>'energy_direction',''),nullif(p_underlay#>>'{payload,energy_direction}',''),'consumption');
  v_settlement_type text := coalesce(nullif(p_underlay->>'settlement_type',''),nullif(p_underlay#>>'{payload,settlement_type}',''));
begin
  if p_company_id is null or v_customer_id is null or v_metering_point_id is null then
    raise exception 'billing_underlay_tenant_customer_meter_required' using errcode='22023';
  end if;
  if v_end_instant <= v_start_instant or v_end_date <= v_start_date then
    raise exception 'billing_underlay_invalid_segment' using errcode='22023';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then raise exception 'billing_underlay_items_must_be_array' using errcode='22023'; end if;
  if v_energy_direction not in ('consumption','production','consumption_correction') then raise exception 'billing_underlay_invalid_energy_direction' using errcode='22023'; end if;
  if not exists(select 1 from public.customers where company_id=p_company_id and id=v_customer_id) then raise exception 'billing_underlay_customer_tenant_mismatch' using errcode='23503'; end if;
  if not exists(select 1 from public.metering_points where company_id=p_company_id and id=v_metering_point_id) then raise exception 'billing_underlay_meter_tenant_mismatch' using errcode='23503'; end if;

  insert into public.billing_underlays(
    company_id,customer_id,site_id,customer_site_id,metering_point_id,supply_period_id,contract_id,pricing_snapshot_id,
    price_plan_id,price_plan_version_id,price_book_id,contract_price_snapshot_id,billing_block_reason,campaign_id,price_area,
    energy_direction,settlement_type,underlay_month,underlay_year,billing_period_start,billing_period_end,status,readiness_status,
    readiness_issues,total_kwh,currency,source_system,source_meter_value_count,missing_values_count,payload,pricing_snapshot,
    received_at,validated_at,created_by,updated_by,updated_at
  ) values (
    p_company_id,v_customer_id,nullif(p_underlay->>'site_id','')::uuid,nullif(p_underlay->>'customer_site_id','')::uuid,v_metering_point_id,
    nullif(p_underlay->>'supply_period_id','')::uuid,nullif(p_underlay->>'contract_id','')::uuid,nullif(p_underlay->>'pricing_snapshot_id','')::uuid,
    nullif(p_underlay->>'price_plan_id','')::uuid,nullif(p_underlay->>'price_plan_version_id','')::uuid,nullif(p_underlay->>'price_book_id','')::uuid,
    nullif(p_underlay->>'contract_price_snapshot_id','')::uuid,nullif(p_underlay->>'billing_block_reason',''),nullif(p_underlay->>'campaign_id','')::uuid,
    nullif(p_underlay->>'price_area',''),v_energy_direction,v_settlement_type,v_month,v_year,v_start_date,v_end_date,
    coalesce(nullif(p_underlay->>'status',''),'pending'),coalesce(nullif(p_underlay->>'readiness_status',''),'blocked'),
    coalesce(p_underlay->'readiness_issues','[]'::jsonb),(p_underlay->>'total_kwh')::numeric,coalesce(nullif(p_underlay->>'currency',''),'SEK'),
    coalesce(nullif(p_underlay->>'source_system',''),'normalized_metering_values'),coalesce((p_underlay->>'source_meter_value_count')::integer,0),
    coalesce((p_underlay->>'missing_values_count')::integer,0),coalesce(p_underlay->'payload','{}'::jsonb)||jsonb_build_object(
      'billing_period_start_instant',v_start_instant,'billing_period_end_instant',v_end_instant,'billing_period_timezone','Europe/Stockholm','billing_period_end_exclusive',true
    ),coalesce(p_underlay->'pricing_snapshot','{}'::jsonb),coalesce((p_underlay->>'received_at')::timestamptz,now()),
    nullif(p_underlay->>'validated_at','')::timestamptz,p_actor_user_id,p_actor_user_id,now()
  )
  on conflict(company_id,customer_id,metering_point_id,underlay_year,underlay_month,billing_period_start,billing_period_end,energy_direction)
  do update set
    site_id=excluded.site_id,customer_site_id=excluded.customer_site_id,supply_period_id=excluded.supply_period_id,contract_id=excluded.contract_id,
    pricing_snapshot_id=excluded.pricing_snapshot_id,price_plan_id=excluded.price_plan_id,price_plan_version_id=excluded.price_plan_version_id,
    price_book_id=excluded.price_book_id,contract_price_snapshot_id=excluded.contract_price_snapshot_id,billing_block_reason=excluded.billing_block_reason,
    campaign_id=excluded.campaign_id,price_area=excluded.price_area,status=excluded.status,readiness_status=excluded.readiness_status,
    readiness_issues=excluded.readiness_issues,total_kwh=excluded.total_kwh,currency=excluded.currency,source_system=excluded.source_system,
    source_meter_value_count=excluded.source_meter_value_count,missing_values_count=excluded.missing_values_count,payload=excluded.payload,
    pricing_snapshot=excluded.pricing_snapshot,received_at=excluded.received_at,validated_at=excluded.validated_at,updated_by=p_actor_user_id,updated_at=now()
  returning id into v_id;

  delete from public.billing_underlay_items where company_id=p_company_id and billing_underlay_id=v_id;
  insert into public.billing_underlay_items
  select (jsonb_populate_record(null::public.billing_underlay_items,
    item || jsonb_build_object('id',gen_random_uuid(),'company_id',p_company_id,'billing_underlay_id',v_id,'created_at',now(),'updated_at',now()))).*
  from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) item;

  insert into public.billing_underlay_events(company_id,billing_underlay_id,event_type,message,metadata,created_by)
  values(p_company_id,v_id,'underlay_generated',case when p_underlay->>'readiness_status'='ready' then 'Fakturaunderlag är redo för prisberäkning.' else 'Fakturaunderlag är blockerat.' end,
    jsonb_build_object('billing_period_start',v_start_date,'billing_period_end',v_end_date,'billing_period_start_instant',v_start_instant,'billing_period_end_instant',v_end_instant,'billing_period_timezone','Europe/Stockholm','billing_period_end_exclusive',true,'energy_direction',v_energy_direction,'source_rows',jsonb_array_length(coalesce(p_items,'[]'::jsonb))),p_actor_user_id);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_store_billing_underlay_batch(p_company_id uuid, p_commands jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_command jsonb;
  v_ids jsonb:='[]'::jsonb;
  v_id uuid;
begin
  if jsonb_typeof(coalesce(p_commands,'[]'::jsonb))<>'array' then
    raise exception using errcode='22023',message='billing_underlay_commands_must_be_array';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':billing-underlay-batch',0));
  for v_command in select value from jsonb_array_elements(coalesce(p_commands,'[]'::jsonb)) loop
    v_id:=public.gridex_store_billing_underlay(
      p_company_id,
      coalesce(v_command->'underlay','{}'::jsonb),
      coalesce(v_command->'items','[]'::jsonb),
      p_actor_user_id
    );
    v_ids:=v_ids||jsonb_build_array(v_id::text);
  end loop;
  return v_ids;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_transition_portfolio_settlement(p_actor_user_id uuid, p_settlement_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_row public.portfolio_monthly_settlements%rowtype;
  v_price numeric;
  v_hash text;
  v_formula text;
  v_snapshot jsonb;
  v_now timestamptz := now();
begin
  select *
    into v_row
  from public.portfolio_monthly_settlements
  where id = p_settlement_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'portfolio_settlement_not_found';
  end if;

  perform set_config('gridex.portfolio_actor_user_id', p_actor_user_id::text, true);
  perform set_config('gridex.portfolio_audit_reason', coalesce(p_reason, ''), true);

  if p_action = 'calculate' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.calculate',
      v_row.company_id,
      v_row.portfolio_id
    );

    if v_row.status not in ('draft', 'calculated') then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_draft_or_calculated';
    end if;

    if v_row.portfolio_price_ore_per_kwh is not null then
      if v_row.portfolio_price_ore_per_kwh <= 0 then
        raise exception using errcode = '23514', message = 'portfolio_settlement_direct_price_invalid';
      end if;
      v_price := v_row.portfolio_price_ore_per_kwh;
      v_formula := 'manual_portfolio_price_ore_per_kwh';
    else
      if v_row.gross_energy_cost_sek is null or coalesce(v_row.energy_volume_kwh, 0) <= 0 then
        raise exception using errcode = '23514', message = 'portfolio_settlement_calculation_inputs_missing';
      end if;
      v_price := (
        (
          v_row.gross_energy_cost_sek
          + v_row.hedging_result_sek
          + v_row.balancing_cost_sek
          + v_row.other_allowed_cost_sek
        ) / v_row.energy_volume_kwh
      ) * 100;
      v_formula := '((gross_energy_cost_sek + hedging_result_sek + balancing_cost_sek + other_allowed_cost_sek) / energy_volume_kwh) * 100';
    end if;

    v_snapshot := jsonb_build_object(
      'formula', v_formula,
      'source', v_row.source,
      'company_id', v_row.company_id,
      'portfolio_id', v_row.portfolio_id,
      'price_area_code', v_row.price_area_code,
      'delivery_month', v_row.delivery_month,
      'price_plan_version_id', v_row.price_plan_version_id,
      'revision_no', v_row.revision_no,
      'gross_energy_cost_sek', v_row.gross_energy_cost_sek,
      'hedging_result_sek', v_row.hedging_result_sek,
      'balancing_cost_sek', v_row.balancing_cost_sek,
      'other_allowed_cost_sek', v_row.other_allowed_cost_sek,
      'energy_volume_kwh', v_row.energy_volume_kwh,
      'management_fee_ore_per_kwh', v_row.management_fee_ore_per_kwh,
      'portfolio_price_ore_per_kwh', v_price,
      'vat_rate', v_row.vat_rate
    );
    v_hash := encode(
      extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'),
      'hex'
    );

    update public.portfolio_monthly_settlements
    set status = 'calculated',
        portfolio_price_ore_per_kwh = v_price,
        calculation_snapshot = v_snapshot,
        calculation_snapshot_sha256 = v_hash,
        calculated_by = p_actor_user_id,
        calculated_at = v_now,
        updated_at = v_now
    where id = v_row.id;

  elsif p_action = 'review' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.review',
      v_row.company_id,
      v_row.portfolio_id
    );
    if v_row.status <> 'calculated' then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_calculated';
    end if;
    update public.portfolio_monthly_settlements
    set status = 'reviewed',
        reviewed_by = p_actor_user_id,
        reviewed_at = v_now,
        updated_at = v_now
    where id = v_row.id;

  elsif p_action = 'approve' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.approve',
      v_row.company_id,
      v_row.portfolio_id
    );
    if v_row.status <> 'reviewed'
       or v_row.calculation_snapshot_sha256 is null
       or v_row.portfolio_price_ore_per_kwh is null then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_reviewed_and_calculated';
    end if;
    update public.portfolio_monthly_settlements
    set status = 'final',
        approved_by = p_actor_user_id,
        approved_at = v_now,
        updated_at = v_now
    where id = v_row.id;

  elsif p_action = 'lock' then
    perform public.gridex_assert_portfolio_permission(
      p_actor_user_id,
      'portfolio_settlement.lock',
      v_row.company_id,
      v_row.portfolio_id
    );
    if v_row.status <> 'final' then
      raise exception using errcode = '23514', message = 'portfolio_settlement_must_be_final';
    end if;
    update public.portfolio_monthly_settlements
    set status = 'locked',
        locked_by = p_actor_user_id,
        locked_at = v_now
    where id = v_row.id;

  else
    raise exception using errcode = '22023', message = 'unknown_portfolio_settlement_action';
  end if;

  return (
    select to_jsonb(s)
    from public.portfolio_monthly_settlements s
    where s.id = v_row.id
  );
end $function$

