CREATE OR REPLACE FUNCTION public.gridex_billing_underlay_item_gate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  n public.normalized_metering_values%rowtype;
  u public.billing_underlays%rowtype;
  v_value_start_date date;
  v_value_end_date date;
begin
  if new.source_normalized_metering_value_id is null then raise exception 'billing_underlay_source_normalized_value_required' using errcode='23514'; end if;
  select * into n from public.normalized_metering_values where id=new.source_normalized_metering_value_id;
  select * into u from public.billing_underlays where id=new.billing_underlay_id;
  if not found or u.id is null then raise exception 'billing_underlay_missing' using errcode='23503'; end if;
  if n.id is null then raise exception 'billing_underlay_normalized_value_missing' using errcode='23503'; end if;
  if n.company_id<>new.company_id or u.company_id<>new.company_id then raise exception 'billing_underlay_lineage_tenant_mismatch' using errcode='23514'; end if;
  if n.revision_status<>'current' or n.billing_status<>'billable' or n.billing_gate_status<>'eligible' then raise exception 'billing_underlay_value_not_gate_eligible' using errcode='23514'; end if;
  if n.source_message_id is null or n.source_metering_value_id is null or n.supply_period_id is null then raise exception 'billing_underlay_lineage_incomplete' using errcode='23514'; end if;
  if u.supply_period_id is null or u.supply_period_id<>n.supply_period_id then raise exception 'billing_underlay_supply_period_mismatch' using errcode='23514'; end if;

  v_value_start_date := (n.period_start at time zone 'Europe/Stockholm')::date;
  v_value_end_date := (n.period_end at time zone 'Europe/Stockholm')::date;
  if v_value_start_date < u.billing_period_start or v_value_end_date > u.billing_period_end then
    raise exception 'billing_underlay_period_outside_segment'
      using errcode='23514', detail=jsonb_build_object(
        'normalized_metering_value_id',n.id,
        'value_start_date',v_value_start_date,
        'value_end_date',v_value_end_date,
        'billing_period_start',u.billing_period_start,
        'billing_period_end',u.billing_period_end,
        'timezone','Europe/Stockholm',
        'billing_period_end_exclusive',true
      )::text;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_customer_contract_chain_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_customer_id uuid:=nullif(v_row->>'customer_id','')::uuid;
  v_contract_id uuid:=coalesce(
    nullif(v_row->>'customer_contract_id','')::uuid,
    nullif(v_row->>'contract_id','')::uuid
  );
  v_metering_point_id uuid:=nullif(v_row->>'metering_point_id','')::uuid;
  v_underlay_id uuid:=nullif(v_row->>'billing_underlay_id','')::uuid;
  v_export_item_id uuid:=coalesce(
    nullif(v_row->>'invoice_export_item_id','')::uuid,
    nullif(v_row->>'canonical_export_item_id','')::uuid
  );
begin
  if v_company_id is null or v_customer_id is null then
    raise exception using errcode='23502',message='customer_chain_company_customer_required';
  end if;
  if v_contract_id is not null and not exists(
    select 1 from public.customer_contracts cc
    where cc.id=v_contract_id
      and cc.company_id=v_company_id
      and cc.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_contract_mismatch';
  end if;
  if v_metering_point_id is not null and not exists(
    select 1 from public.metering_points mp
    where mp.id=v_metering_point_id
      and mp.company_id=v_company_id
      and mp.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_metering_point_mismatch';
  end if;
  if v_underlay_id is not null and not exists(
    select 1 from public.billing_underlays bu
    where bu.id=v_underlay_id
      and bu.company_id=v_company_id
      and bu.customer_id=v_customer_id
      and (
        v_contract_id is null
        or coalesce(bu.customer_contract_id,bu.contract_id)=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_underlay_mismatch';
  end if;
  if v_export_item_id is not null and not exists(
    select 1 from public.invoice_export_items iei
    where iei.id=v_export_item_id
      and iei.company_id=v_company_id
      and iei.customer_id=v_customer_id
      and (
        v_contract_id is null
        or iei.customer_contract_id=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_export_item_mismatch';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_billing_underlay_price_area()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract_id uuid := coalesce(new.contract_id, new.customer_contract_id);
  v_contract_snapshot_id uuid;
  v_contract_area text;
  v_snapshot_area text;
  v_legacy_snapshot_area text;
  v_metadata_area text;
  v_canonical_area text;
begin
  if v_contract_id is null then
    return new;
  end if;

  select
    c.contract_price_snapshot_id,
    upper(nullif(btrim(c.price_area_used), '')),
    upper(nullif(btrim(c.price_snapshot #>> '{snapshot_json,price_area}'), '')),
    upper(nullif(btrim(c.metadata ->> 'selected_price_area'), ''))
  into
    v_contract_snapshot_id,
    v_contract_area,
    v_legacy_snapshot_area,
    v_metadata_area
  from public.customer_contracts c
  where c.id = v_contract_id
    and c.company_id = new.company_id;

  if not found then
    return new;
  end if;

  select upper(nullif(btrim(s.snapshot_json ->> 'price_area'), ''))
  into v_snapshot_area
  from public.contract_price_snapshots s
  where s.id = coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
    and s.contract_id = v_contract_id
    and s.company_id = new.company_id;

  v_canonical_area := coalesce(
    case when v_snapshot_area in ('SE1','SE2','SE3','SE4') then v_snapshot_area end,
    case when v_contract_area in ('SE1','SE2','SE3','SE4') then v_contract_area end,
    case when v_legacy_snapshot_area in ('SE1','SE2','SE3','SE4') then v_legacy_snapshot_area end,
    case when v_metadata_area in ('SE1','SE2','SE3','SE4') then v_metadata_area end
  );

  if coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id) is not null
     and v_canonical_area is null then
    raise exception 'billing_contract_price_area_missing'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  end if;

  if v_canonical_area is null then
    return new;
  end if;

  if new.price_area is null or nullif(btrim(new.price_area), '') is null then
    new.price_area := v_canonical_area;
  elsif upper(btrim(new.price_area)) <> v_canonical_area then
    raise exception 'billing_underlay_price_area_mismatch'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'submitted_price_area', upper(btrim(new.price_area)),
              'canonical_price_area', v_canonical_area,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  else
    new.price_area := v_canonical_area;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_assert_company_operational_for_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
