CREATE OR REPLACE FUNCTION public.gridex_assign_public_offer_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  base_code text;
  candidate text;
  suffix integer := 1;
begin
  base_code := coalesce(
    public.gridex_normalize_public_offer_code(new.offer_code),
    public.gridex_normalize_public_offer_code(new.public_name),
    'AVTAL'
  );
  base_code := left(base_code, 70);
  candidate := base_code;

  while exists (
    select 1
    from public.public_contract_offers existing
    where existing.company_id = new.company_id
      and existing.offer_code = candidate
      and existing.id is distinct from new.id
  ) loop
    suffix := suffix + 1;
    candidate := left(base_code, greatest(1, 80 - length(suffix::text) - 1)) || '-' || suffix::text;

    if suffix > 999 then
      candidate := left(base_code, 62) || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
      exit;
    end if;
  end loop;

  new.offer_code := candidate;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_public_contract_offer_forward_link_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if current_setting('gridex.publication_link_repair',true)='on' then return new; end if;
  perform set_config('gridex.version_transition','on',true);
  perform set_config('gridex.publication_link_repair','on',true);
  if old.contract_publication_version_id is not null
     and old.contract_publication_version_id is distinct from new.contract_publication_version_id then
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=null
    where id=old.contract_publication_version_id
      and legacy_public_contract_offer_id=old.id;
  end if;
  if new.contract_publication_version_id is not null then
    if not exists(
      select 1
      from public.contract_publication_versions cpv
      join public.contract_publications cp on cp.id=cpv.contract_publication_id
      join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
      where cpv.id=new.contract_publication_version_id
        and ta.company_id=new.company_id
        and (new.contract_product_version_id is null or cpv.contract_product_version_id=new.contract_product_version_id)
    ) then
      raise exception using errcode='23514',message='public_offer_forward_publication_link_invalid';
    end if;
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=new.id
    where id=new.contract_publication_version_id
      and legacy_public_contract_offer_id is distinct from new.id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_contract_publication_revision_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_company_id uuid;
  v_channel text;
  v_entity_id text;
  v_assignment_id uuid;
  v_publication_id uuid;
  v_publication_version_id uuid;
  v_option_id uuid;
  v_row jsonb;
begin
  v_row:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_entity_id:=v_row->>'id';
  if tg_table_name='public_contract_offers' then
    v_company_id:=(v_row->>'company_id')::uuid;
    v_channel:='website';
  elsif tg_table_name='tenant_contract_channels' then
    v_assignment_id:=(v_row->>'assignment_id')::uuid;
    v_channel:=v_row->>'channel';
    select company_id into v_company_id
    from public.tenant_contract_assignments where id=v_assignment_id;
  elsif tg_table_name='contract_publications' then
    v_assignment_id:=(v_row->>'assignment_id')::uuid;
    v_channel:=v_row->>'channel';
    select company_id into v_company_id
    from public.tenant_contract_assignments where id=v_assignment_id;
  elsif tg_table_name='contract_publication_versions' then
    v_publication_id:=(v_row->>'contract_publication_id')::uuid;
    select a.company_id,p.channel into v_company_id,v_channel
    from public.contract_publications p
    join public.tenant_contract_assignments a on a.id=p.assignment_id
    where p.id=v_publication_id;
  elsif tg_table_name='contract_price_options' then
    v_company_id:=(v_row->>'company_id')::uuid;
    v_publication_version_id:=nullif(
      v_row->>'contract_publication_version_id',''
    )::uuid;
    if v_publication_version_id is not null then
      select p.channel into v_channel
      from public.contract_publication_versions pv
      join public.contract_publications p on p.id=pv.contract_publication_id
      where pv.id=v_publication_version_id;
    end if;
  elsif tg_table_name='contract_price_option_area_prices' then
    v_option_id:=(v_row->>'contract_price_option_id')::uuid;
    select o.company_id,o.contract_publication_version_id
      into v_company_id,v_publication_version_id
    from public.contract_price_options o where o.id=v_option_id;
    if v_publication_version_id is not null then
      select p.channel into v_channel
      from public.contract_publication_versions pv
      join public.contract_publications p on p.id=pv.contract_publication_id
      where pv.id=v_publication_version_id;
    end if;
  end if;
  if v_company_id is not null and v_channel in ('website','api') then
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,v_channel,tg_table_name||'.'||lower(tg_op),v_entity_id
    );
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_reject_locked_market_price_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
